src='''def transform(grid):
    height, width = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(height) for c in range(width) if grid[r][c] != 0}
    pieces = []
    for r in range(height - 1):
        for c in range(width - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= occupied:
                pieces.append((box, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                piece = box - {missing}
                if piece <= occupied:
                    pieces.append((piece, color))

    def tile(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for piece, color in pieces:
            if cell in piece and piece <= remaining:
                rest = tile(remaining - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    tiling = tile(occupied)
    if tiling is None:
        raise ValueError("Input cannot be tiled by the demonstrated pieces")
    output = [[0] * width for _ in range(height)]
    for piece, color in tiling:
        for r, c in piece:
            output[r][c] = color
    return output
'''
